"""
Convert Trial Balance PDF (12/31/2025) to Excel spreadsheet.
"""
import openpyxl
from openpyxl.styles import Font, Alignment, PatternFill, Border, Side, numbers
from openpyxl.utils import get_column_letter

# All rows: (account_number, description, opening_balance, curr_debit, curr_credit, curr_net, ytd_debit, ytd_credit, balance)
# Negatives stored as negative floats. Blanks/zeros as 0.0.

def n(s):
    """Parse number string from PDF (trailing '-' = negative)."""
    s = s.strip().replace(',', '')
    if s in ('.00', '0', '0.00', '', '.'):
        return 0.0
    if s.endswith('-'):
        return -float(s[:-1])
    return float(s)

