# ── Build workbook ──────────────────────────────────────────────────────────────
wb = openpyxl.Workbook()
ws = wb.active
ws.title = "Trial Balance 12-31-2025"

# Styles
header_font  = Font(name="Calibri", bold=True, color="FFFFFF", size=10)
header_fill  = PatternFill("solid", fgColor="1F4E79")
title_font   = Font(name="Calibri", bold=True, size=12)
subhdr_fill  = PatternFill("solid", fgColor="D6E4F0")
subhdr_font  = Font(name="Calibri", bold=True, size=10)
num_fmt      = '#,##0.00;[Red]-#,##0.00'
thin         = Side(border_style="thin", color="BFBFBF")
thin_border  = Border(left=thin, right=thin, top=thin, bottom=thin)

# Title rows
ws.merge_cells("A1:I1")
ws["A1"] = "OLD MASTER PRODUCTS, INC."
ws["A1"].font = Font(name="Calibri", bold=True, size=14)
ws["A1"].alignment = Alignment(horizontal="center")

ws.merge_cells("A2:I2")
ws["A2"] = "TRIAL BALANCE — PERIOD ENDING 12/31/2025"
ws["A2"].font = Font(name="Calibri", bold=True, size=12)
ws["A2"].alignment = Alignment(horizontal="center")

ws.merge_cells("A3:I3")
ws["A3"] = "Printed: 4/15/2026"
ws["A3"].font = Font(name="Calibri", italic=True, size=10)
ws["A3"].alignment = Alignment(horizontal="center")

# Header row (row 5)
headers = [
    "Account #", "Description",
    "Opening Balance",
    "Curr Debit", "Curr Credit", "Curr Net",
    "YTD Debit", "YTD Credit",
    "Balance"
]
for col, hdr in enumerate(headers, 1):
    cell = ws.cell(row=5, column=col, value=hdr)
    cell.font = header_font
    cell.fill = header_fill
    cell.alignment = Alignment(horizontal="center", wrap_text=True)
    cell.border = thin_border

# Data rows start at row 6
ROW_START = 6
for i, row in enumerate(DATA):
    r = ROW_START + i
    acct, desc, ob, cd, cc, cn, yd, yc, bal = row
    values = [acct, desc, ob, cd, cc, cn, yd, yc, bal]
    for col, val in enumerate(values, 1):
        cell = ws.cell(row=r, column=col, value=val)
        cell.border = thin_border
        if col == 1:
            cell.alignment = Alignment(horizontal="center")
        elif col == 2:
            cell.alignment = Alignment(horizontal="left")
        else:
            cell.number_format = num_fmt
            cell.alignment = Alignment(horizontal="right")
    # Alternate row shading
    if i % 2 == 0:
        for col in range(1, 10):
            ws.cell(row=r, column=col).fill = PatternFill("solid", fgColor="EBF3FB")

# Totals row
total_row = ROW_START + len(DATA)
ws.cell(row=total_row, column=2, value="COMPANY TOTAL").font = Font(bold=True)
for col, label in [(3, "Opening Balance"), (4, "Curr Debit"), (5, "Curr Credit"),
                    (6, "Curr Net"), (7, "YTD Debit"), (8, "YTD Credit"), (9, "Balance")]:
    first = ROW_START
    last  = total_row - 1
    cell = ws.cell(row=total_row, column=col,
                   value=f"=SUM({get_column_letter(col)}{first}:{get_column_letter(col)}{last})")
    cell.number_format = num_fmt
    cell.font = Font(bold=True)
    cell.fill = PatternFill("solid", fgColor="1F4E79")
    cell.font = Font(bold=True, color="FFFFFF")
    cell.border = thin_border
    cell.alignment = Alignment(horizontal="right")
ws.cell(row=total_row, column=1).fill = PatternFill("solid", fgColor="1F4E79")
ws.cell(row=total_row, column=2).fill = PatternFill("solid", fgColor="1F4E79")
ws.cell(row=total_row, column=2).font = Font(bold=True, color="FFFFFF")

# Column widths
col_widths = [12, 32, 18, 18, 18, 18, 18, 18, 18]
for col, w in enumerate(col_widths, 1):
    ws.column_dimensions[get_column_letter(col)].width = w

# Freeze header
ws.freeze_panes = "A6"

# Auto-filter
ws.auto_filter.ref = f"A5:I{total_row - 1}"

output_path = r"h:/2025/NewForecastingModel/OMPforecasting5/TrialBalance_12312025.xlsx"
wb.save(output_path)
print(f"Saved: {output_path}")
print(f"Rows: {len(DATA)} accounts + 1 total row")
